import CoreGraphics
import CoreImage
import Foundation
import ImageIO
import PDFKit

/// Classification label generated by Vision (`Classify Images` node).
public struct ClassificationTag: Hashable, Sendable {
    public let identifier: String
    public let confidence: Float

    public init(identifier: String, confidence: Float) {
        self.identifier = identifier
        self.confidence = confidence
    }
}

/// Asset information snapshot displayed in the `(i)` HUD inspector.
public struct AssetInspectorInfo: Sendable {
    public let fileName: String
    public let pixelWidth: Int
    public let pixelHeight: Int
    public let dpi: Int
    public let colorSpaceName: String
    public let bitsPerChannel: Int
    public let hasAlpha: Bool
    public let originalByteCount: Int64
    public let cameraMake: String?
    public let cameraModel: String?
    public let gpsPresent: Bool
    public let classifications: [ClassificationTag]
}

/// Mutable per-item payload flowing through workflow nodes.
/// Each asset instance is processed exclusively by one task at a time and deep-copied on branch fan-out.
public final class PipelineAsset: @unchecked Sendable {
    public let id: UUID
    public var sourceURL: URL?
    public var fileName: String
    public var fileExtension: String
    public var parentFolderName: String
    public var outputNameOverride: String?
    public var outputSubdirectory: String?

    public var ciImage: CIImage?
    public var pdfData: Data?
    public var animatedFrames: [(image: CIImage, delay: Double)]?

    /// ImageIO-compatible property dictionary (`{Exif}`, `{TIFF}`, `{IPTC}`, `{GPS}`, `DPIWidth`, `Orientation`, ...).
    public var metadata: [String: Any]
    public var classificationLabels: [ClassificationTag]
    public var customVariables: [String: String]

    public var dpi: Int
    public var bitsPerChannel: Int
    public var targetColorSpace: CGColorSpace?
    public var originalByteCount: Int64
    public var sequenceIndex: Int
    public var shouldSkip: Bool = false
    public var creationDate: Date?
    public var modificationDate: Date?
    public var writtenOutputURL: URL?

    public init(
        id: UUID = UUID(),
        sourceURL: URL? = nil,
        fileName: String,
        fileExtension: String = "png",
        parentFolderName: String = "",
        ciImage: CIImage? = nil,
        metadata: [String: Any] = [:],
        dpi: Int = 72,
        bitsPerChannel: Int = 8,
        originalByteCount: Int64 = 0,
        sequenceIndex: Int = 1
    ) {
        self.id = id
        self.sourceURL = sourceURL
        self.fileName = fileName
        self.fileExtension = fileExtension
        self.parentFolderName = parentFolderName
        self.ciImage = ciImage
        self.metadata = metadata
        self.classificationLabels = []
        self.customVariables = [:]
        self.dpi = dpi
        self.bitsPerChannel = bitsPerChannel
        self.originalByteCount = originalByteCount
        self.sequenceIndex = sequenceIndex
    }

    public var pixelSize: CGSize {
        guard let img = ciImage else { return .zero }
        let ext = img.extent
        return ext.isInfinite ? .zero : CGSize(width: round(ext.width), height: round(ext.height))
    }

    public var colorSpaceName: String {
        if let cs = targetColorSpace ?? ciImage?.colorSpace, let name = cs.name as String? {
            return name
        }
        return "sRGB"
    }

    public var hasAlpha: Bool {
        guard let cg = ciImage?.cgImage else { return true }
        switch cg.alphaInfo {
        case .none, .noneSkipFirst, .noneSkipLast:
            return false
        default:
            return true
        }
    }

    public func deepCopy(newIndex: Int? = nil) -> PipelineAsset {
        let copiedMeta = (NSDictionary(dictionary: metadata, copyItems: true) as? [String: Any]) ?? metadata
        let copy = PipelineAsset(
            id: UUID(),
            sourceURL: sourceURL,
            fileName: fileName,
            fileExtension: fileExtension,
            parentFolderName: parentFolderName,
            ciImage: ciImage,
            metadata: copiedMeta,
            dpi: dpi,
            bitsPerChannel: bitsPerChannel,
            originalByteCount: originalByteCount,
            sequenceIndex: newIndex ?? sequenceIndex
        )
        copy.outputNameOverride = outputNameOverride
        copy.outputSubdirectory = outputSubdirectory
        copy.pdfData = pdfData
        copy.animatedFrames = animatedFrames
        copy.classificationLabels = classificationLabels
        copy.customVariables = customVariables
        copy.targetColorSpace = targetColorSpace
        copy.shouldSkip = shouldSkip
        copy.creationDate = creationDate
        copy.modificationDate = modificationDate
        return copy
    }

    public func inspectorInfo() -> AssetInspectorInfo {
        let size = pixelSize
        let tiff = metadata[kCGImagePropertyTIFFDictionary as String] as? [String: Any]
        return AssetInspectorInfo(
            fileName: fileName + (fileExtension.isEmpty ? "" : ".\(fileExtension)"),
            pixelWidth: Int(size.width),
            pixelHeight: Int(size.height),
            dpi: dpi,
            colorSpaceName: colorSpaceName,
            bitsPerChannel: bitsPerChannel,
            hasAlpha: hasAlpha,
            originalByteCount: originalByteCount,
            cameraMake: tiff?[kCGImagePropertyTIFFMake as String] as? String,
            cameraModel: tiff?[kCGImagePropertyTIFFModel as String] as? String,
            gpsPresent: metadata[kCGImagePropertyGPSDictionary as String] != nil,
            classifications: classificationLabels
        )
    }

    /// Loads an image (or PDF first page) from disk with memory-conscious options.
    /// For interactive preview, pass `subsampleFactor` (2, 4, or 8) or `rawScaleFactor` (`< 1.0`).
    public static func load(
        from url: URL,
        sequenceIndex: Int,
        rawScaleFactor: Float = 1.0,
        subsampleFactor: Int = 1
    ) throws -> PipelineAsset {
        let fm = FileManager.default
        let attrs = try? fm.attributesOfItem(atPath: url.path)
        let byteSize = (attrs?[.size] as? NSNumber)?.int64Value ?? 0
        let created = attrs?[.creationDate] as? Date
        let modified = attrs?[.modificationDate] as? Date

        let baseName = url.deletingPathExtension().lastPathComponent
        let ext = url.pathExtension.lowercased()
        let parent = url.deletingLastPathComponent().lastPathComponent

        if ext == "pdf", let data = try? Data(contentsOf: url), let pdf = PDFDocument(data: data), let page = pdf.page(at: 0) {
            let bounds = page.bounds(for: .mediaBox)
            let scale: CGFloat = 2.0
            let w = max(1, Int(bounds.width * scale))
            let h = max(1, Int(bounds.height * scale))
            let rep = NSBitmapImageRep(
                bitmapDataPlanes: nil, pixelsWide: w, pixelsHigh: h,
                bitsPerSample: 8, samplesPerPixel: 4, hasAlpha: true,
                isPlanar: false, colorSpaceName: .deviceRGB, bytesPerRow: 0, bitsPerPixel: 0
            )
            var ci: CIImage?
            if let rep {
                NSGraphicsContext.saveGraphicsState()
                NSGraphicsContext.current = NSGraphicsContext(bitmapImageRep: rep)
                NSColor.white.setFill()
                NSRect(x: 0, y: 0, width: w, height: h).fill()
                if let cgCtx = NSGraphicsContext.current?.cgContext {
                    cgCtx.scaleBy(x: scale, y: scale)
                    page.draw(with: .mediaBox, to: cgCtx)
                }
                NSGraphicsContext.restoreGraphicsState()
                if let cg = rep.cgImage { ci = CIImage(cgImage: cg) }
            }
            let asset = PipelineAsset(
                sourceURL: url, fileName: baseName, fileExtension: ext,
                parentFolderName: parent, ciImage: ci, dpi: 144,
                originalByteCount: byteSize, sequenceIndex: sequenceIndex
            )
            asset.pdfData = data
            asset.creationDate = created
            asset.modificationDate = modified
            return asset
        }

        // Extract ImageIO metadata without decoding full bitmap
        var metadata: [String: Any] = [:]
        var dpi = 72
        var bpc = 8
        if let src = CGImageSourceCreateWithURL(url as CFURL, [kCGImageSourceShouldCache: false] as CFDictionary),
           let props = CGImageSourceCopyPropertiesAtIndex(src, 0, nil) as? [String: Any] {
            metadata = props
            if let d = props[kCGImagePropertyDPIWidth as String] as? NSNumber, d.intValue > 0 {
                dpi = d.intValue
            }
            if let depth = props[kCGImagePropertyDepth as String] as? NSNumber, depth.intValue > 0 {
                bpc = depth.intValue
            }
        }

        let rawExtensions: Set<String> = ["dng", "cr2", "cr3", "nef", "arw", "orf", "raf", "rw2", "srw"]
        var loadedCI: CIImage?
        if rawExtensions.contains(ext), let rawFilter = CIRAWFilter(imageURL: url) {
            rawFilter.scaleFactor = max(0.05, min(1.0, rawScaleFactor))
            if let out = rawFilter.outputImage, !out.extent.isEmpty {
                loadedCI = out
            }
        }

        if loadedCI == nil {
            var ciOptions: [CIImageOption: Any] = [.applyOrientationProperty: true]
            if #available(macOS 27.0, *), subsampleFactor > 1 {
                let validFactor = [2, 4, 8].min(by: { abs($0 - subsampleFactor) < abs($1 - subsampleFactor) }) ?? 2
                ciOptions[.subsampleFactor] = validFactor
            }
            if let candidate = CIImage(contentsOf: url, options: ciOptions), !candidate.extent.isEmpty {
                loadedCI = candidate
            }
        }

        // Normalize extent origin to (0, 0)
        if let ci = loadedCI, ci.extent.origin != .zero, !ci.extent.isInfinite {
            loadedCI = ci.transformed(by: CGAffineTransform(translationX: -ci.extent.origin.x, y: -ci.extent.origin.y))
        }

        let asset = PipelineAsset(
            sourceURL: url,
            fileName: baseName,
            fileExtension: ext,
            parentFolderName: parent,
            ciImage: loadedCI,
            metadata: metadata,
            dpi: dpi,
            bitsPerChannel: bpc,
            originalByteCount: byteSize,
            sequenceIndex: sequenceIndex
        )
        asset.creationDate = created
        asset.modificationDate = modified
        return asset
    }
}
